content:
:root {
  --primary-color: #ff6b6b;
  --secondary-color: #4dabf7;
  --bg-color: #f8f9fa;
  --card-bg: #ffffff;
  --text-color: #343a40;
  --text-muted: #868e96;
  --border-radius: 16px;
  --shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

button:focus-visible,
.btn:focus-visible {
  outline: 3px solid var(--primary-color);
  outline-offset: 2px;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 20px;
}

.app-container {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.timer-card {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow);
  padding: 32px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  text-align: center;
}

.mode-selector {
  display: flex;
  background-color: #f1f3f5;
  padding: 4px;
  border-radius: 30px;
  gap: 4px;
  width: 100%;
  max-width: 280px;
}

.mode-selector .btn {
  flex: 1;
  padding: 8px 16px;
  font-size: 14px;
  border-radius: 20px;
  background: transparent;
  color: var(--text-muted);
  box-shadow: none;
}

.mode-selector .btn.active {
  background-color: var(--card-bg);
  color: var(--text-color);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.status-text {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.timer-display {
  font-size: 72px;
  font-weight: 700;
  letter-spacing: -2px;
  color: var(--text-color);
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
}

.btn {
  cursor: pointer;
  border: none;
  border-radius: 12px;
  padding: 12px 24px;
  font-size: 16px;
  font-weight: 600;
  transition: transform 0.1s ease, background-color 0.2s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(255, 107, 107, 0.3);
}

.btn-primary:hover {
  opacity: 0.9;
}

.btn-secondary {
  background-color: #f1f3f5;
  color: var(--text-color);
}

.btn-secondary:hover {
  background-color: #e9ecef;
}

.counter-text {
  font-size: 14px;
  color: var(--text-muted);
  font-weight: 500;
}

@media (max-width: 480px) {
  body {
    padding: 12px;
  }

  .timer-card {
    padding: 20px 16px;
    gap: 16px;
  }

  .timer-display {
    font-size: 56px;
  }

  .controls {
    flex-direction: column;
  }

  .btn {
    width: 100%;
  }
}

export type TimerMode = 'work' | 'break';

export interface TimerState {
  timeLeft: number;
  isRunning: boolean;
  mode: TimerMode;
  completedCount: number;
  workDuration?: number;
  breakDuration?: number;
}

import { useState, useEffect } from 'react';
import { TimerMode, TimerState } from './types';

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

const playAlarmSound = () => {
  try {
    const audioCtx = new (window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(587.33, audioCtx.currentTime);
    gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + 0.5);
  } catch {
    // Ignore audio context errors if blocked by browser policy
  }
};

export default function App() {
  const [state, setState] = useState<TimerState>(() => {
    const savedCount = localStorage.getItem('pomodoro_completed_count');
    const completedCount = savedCount ? parseInt(savedCount, 10) || 0 : 0;
    return {
      timeLeft: WORK_TIME,
      isRunning: false,
      mode: 'work',
      completedCount,
    };
  });

  const [endTime, setEndTime] = useState<number | null>(null);

  useEffect(() => {
    localStorage.setItem('pomodoro_completed_count', state.completedCount.toString());
  }, [state.completedCount]);

  useEffect(() => {
    let timer: number | undefined;
    if (state.isRunning && endTime !== null) {
      timer = window.setInterval(() => {
        const now = Date.now();
        const remaining = Math.max(0, Math.round((endTime - now) / 1000));

        if (remaining <= 0) {
          playAlarmSound();
          setState((prev) => {
            const nextMode: TimerMode = prev.mode === 'work' ? 'break' : 'work';
            const nextTime = nextMode === 'work' ? WORK_TIME : BREAK_TIME;
            const newCompletedCount = prev.mode === 'work' ? prev.completedCount + 1 : prev.completedCount;
            return {
              ...prev,
              timeLeft: nextTime,
              mode: nextMode,
              isRunning: false,
              completedCount: newCompletedCount,
            };
          });
          setEndTime(null);
        } else {
          setState((prev) => ({ ...prev, timeLeft: remaining }));
        }
      }, 200);
    }
    return () => clearInterval(timer);
  }, [state.isRunning, endTime]);

  const toggleTimer = () => {
    if (!state.isRunning) {
      const target = Date.now() + state.timeLeft * 1000;
      setEndTime(target);
      setState((prev) => ({ ...prev, isRunning: true }));
    } else {
      setEndTime(null);
      setState((prev) => ({ ...prev, isRunning: false }));
    }
  };

  const resetTimer = () => {
    setEndTime(null);
    setState((prev) => ({
      ...prev,
      isRunning: false,
      timeLeft: prev.mode === 'work' ? WORK_TIME : BREAK_TIME,
    }));
  };

  const changeMode = (mode: TimerMode) => {
    setEndTime(null);
    const time = mode === 'work' ? WORK_TIME : BREAK_TIME;
    setState((prev) => ({
      ...prev,
      timeLeft: time,
      isRunning: false,
      mode,
    }));
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="app-container">
      <div className="timer-card">
        <div className="mode-selector">
          <button
            className={`btn ${state.mode === 'work' ? 'active' : ''}`}
            onClick={() => changeMode('work')}
          >
            作業
          </button>
          <button
            className={`btn ${state.mode === 'break' ? 'active' : ''}`}
            onClick={() => changeMode('break')}
          >
            休憩
          </button>
        </div>

        <div className="status-text">
          {state.mode === 'work' ? '集中タイム' : '休憩タイム'}
        </div>

        <div className="timer-display">
          {formatTime(state.timeLeft)}
        </div>

        <div className="controls">
          <button className="btn btn-primary" onClick={toggleTimer}>
            {state.isRunning ? '一時停止' : 'スタート'}
          </button>
          <button className="btn btn-secondary" onClick={resetTimer}>
            リセット
          </button>
        </div>

        <div className="counter-text">
          完了したポモドーロ: {state.completedCount} 回
        </div>
      </div>
    </div>
  );
}
